SELECT cs.canonical_smiles, md.chembl_id, act.standard_type, act.standard_relation, act.standard_value, act.standard_units FROM activities act INNER JOIN assays a ON act.assay_id = a.assay_id INNER JOIN compound_structures cs ON act.molregno = cs.molregno INNER JOIN molecule_dictionary md ON act.molregno = md.molregno WHERE a.chembl_id = 'CHEMBL1040694' AND act.standard_value IS NOT NULL AND act.standard_relation = '=' ORDER BY cs.canonical_smiles, md.chembl_id, act.standard_type, act.standard_relation, act.standard_value, act.standard_units
